module ipsxe_divider_lutmult_drm_v1_0 #(
    parameter DIVIDEND_WIDTH = 8,
    parameter SIGNED = 0,
    parameter DIVISOR_WIDTH = 8
)
(
    input clk,
    input rstn,
    input clk_en,
    input [DIVISOR_WIDTH - 1:0] addr_in_signed,		//input divisor under unsigned mode, which is used as address in this drm module
    input [DIVIDEND_WIDTH - 1:0] dividend_signed,	// input dividend under unsigned mode
	input [DIVISOR_WIDTH - 1:0] addr_in_unsigned,	//input divisor under signed mode, which is used as address in this drm module
    input [DIVIDEND_WIDTH - 1:0] dividend_unsigned, // input dividend under signed mode
    input dividend_sign_bit_signed, //input sign bit under signed mode
    input divisor_sign_bit_signed,  //input sign bit under signed mode
    output reg dividend_sign_bit_pass_signed =0,  //output by pass sign bit under signed mode. 
    output reg divisor_sign_bit_pass_signed=0,   //output by pass sign bit under signed mode. 
    output reg [16:0] Lut_out={17{1'b0}},  //output multiplier to the core, which is from drm 
    output reg [DIVIDEND_WIDTH - 1:0] dividend_out_signed={DIVIDEND_WIDTH{1'b0}},		//output divisor under unsigned mode
    output reg [DIVISOR_WIDTH - 1:0] divisor_out_signed={DIVISOR_WIDTH{1'b0}},		// output dividend under unsigned mode
	output reg [DIVIDEND_WIDTH - 1:0] dividend_out_unsigned={DIVIDEND_WIDTH{1'b0}},	//output divisor under signed mode
    output reg [DIVISOR_WIDTH - 1:0] divisor_out_unsigned={DIVISOR_WIDTH{1'b0}}		// output dividend under signed mode
    
);
    reg [16:0] mem [2**DIVISOR_WIDTH - 1:0]; // drm declaration
generate
if (SIGNED == 1) begin	//A generate if block. Circuit is generated only when SIGNED is 1

    always@(posedge clk or negedge rstn)begin
        if(!rstn)begin
            Lut_out <= 17'd0;
        end
        else if (clk_en) begin
            Lut_out <= mem[addr_in_signed];  // address to output
        end
		else begin
            Lut_out <= Lut_out;  // keep
		end
    end

    always@(posedge clk or negedge rstn)begin
        if(!rstn)begin 
            dividend_out_signed <= 0;
            divisor_out_signed <= 0;
            dividend_sign_bit_pass_signed <= 0;
            divisor_sign_bit_pass_signed <= 0;
        end 
        else if (clk_en) begin // by pass all data
            dividend_out_signed <= dividend_signed;
            divisor_out_signed <= addr_in_signed;
            dividend_sign_bit_pass_signed <= dividend_sign_bit_signed;
            divisor_sign_bit_pass_signed <= divisor_sign_bit_signed;
        end
		else begin
            dividend_out_signed <= dividend_out_signed;
            divisor_out_signed <= divisor_out_signed;
            dividend_sign_bit_pass_signed <= dividend_sign_bit_pass_signed;
            divisor_sign_bit_pass_signed <= divisor_sign_bit_pass_signed;
		end
    end
end
else begin				//A generate if block. Circuit is generated only when SIGNED is 0

    always@(posedge clk or negedge rstn)begin
        if(!rstn)begin
            Lut_out <= 17'd0;
        end
        else if (clk_en) begin
            Lut_out <= mem[addr_in_unsigned]; // address to output
        end
		else begin
            Lut_out <= Lut_out; // keep
		end
    end

    always@(posedge clk or negedge rstn)begin
        if(!rstn)begin 
            dividend_out_unsigned <= 0;
            divisor_out_unsigned <= 0;
        end 
        else if (clk_en) begin	// by pass all data
            dividend_out_unsigned <= dividend_unsigned;
            divisor_out_unsigned <= addr_in_unsigned;
        end
		else begin  //keep
            dividend_out_unsigned <= dividend_out_unsigned;
            divisor_out_unsigned <= divisor_out_unsigned;
		end	
    end
end
endgenerate
